import fs from "node:fs";
import path from "node:path";
import { config } from "../config.js";
import { log } from "../logger.js";

const MARKER = "# AUTO-GENERATED BY ANTIMUSIC";

function yamlString(value) {
  return `"${String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

/**
 * Builds the Lavalink application.yml.
 *
 * The generated file always matches the bot configuration (port + password),
 * which removes the classic "401 Unauthorized / connection refused" class of
 * bugs caused by an .env and an application.yml drifting apart.
 */
export function renderLavalinkConfig() {
  const {
    port,
    password,
    youtubePlugin,
    youtubeClients,
    youtubeOAuth,
    youtubeRefreshToken,
    youtubePoToken,
    youtubeVisitorData,
    youtubeRemoteCipherUrl,
    youtubeRemoteCipherPassword,
    youtubeRemoteCipherUserAgent,
  } = config.lavalink;

  const clients = (youtubeClients.length
    ? youtubeClients
    : ["MUSIC", "ANDROID_VR", "WEB", "WEBEMBEDDED", "TVHTML5_SIMPLY", "MWEB"]
  )
    .map((client) => `      - ${client}`)
    .join("\n");

  // OAuth: kalau diaktifkan tanpa refresh token, biarkan alur device-code
  // berjalan supaya token bisa diambil dari console (versi lama mematikannya
  // diam-diam sehingga tidak pernah bisa dipakai).
  const oauth = youtubeOAuth
    ? `    oauth:
      enabled: true
      refreshToken: ${yamlString(youtubeRefreshToken)}
      skipInitialization: false`
    : `    oauth:
      enabled: false
      refreshToken: ""`;

  // poToken (berlaku untuk client WEB / WEBEMBEDDED) - alternatif OAuth.
  const pot =
    youtubePoToken && youtubeVisitorData
      ? `    pot:
      token: ${yamlString(youtubePoToken)}
      visitorData: ${yamlString(youtubeVisitorData)}`
      : "";

  // Remote cipher server (yt-cipher) - mengatasi "must find sig function".
  const remoteCipher = youtubeRemoteCipherUrl
    ? `    remoteCipher:
      url: ${yamlString(youtubeRemoteCipherUrl)}
      password: ${yamlString(youtubeRemoteCipherPassword)}
      userAgent: ${yamlString(youtubeRemoteCipherUserAgent)}`
    : "";

  /* ---------------------------------------------------------------- */
  /* LavaSrc: Spotify / Apple Music / Deezer                           */
  /* ---------------------------------------------------------------- */

  const { musicSources } = config;
  const spotifyReady = Boolean(musicSources.spotify.enabled);
  const appleReady = Boolean(musicSources.appleMusic.enabled);
  const deezerReady = Boolean(musicSources.deezer.enabled);
  const lavasrcReady = musicSources.lavasrcEnabled && (spotifyReady || appleReady || deezerReady);

  const lavasrcPlugin = lavasrcReady
    ? `
    - dependency: "com.github.topi314.lavasrc:lavasrc-plugin:${musicSources.pluginVersion}"
      snapshot: false`
    : "";

  const lavasrcBlock = lavasrcReady
    ? `
  lavasrc:
    providers:
${musicSources.providers.map((provider) => `      - ${yamlString(provider)}`).join("\n")}
    sources:
      spotify: ${spotifyReady}
      applemusic: ${appleReady}
      deezer: ${deezerReady}
      yandexmusic: false
      flowerytts: false
      youtube: false
      vkmusic: false
      tidal: false
      qobuz: false
      ytdlp: false
      jiosaavn: false
    lyrics-sources:
      spotify: false
      deezer: false
      youtube: false
      lrcLib: true
${
  spotifyReady
    ? `    spotify:
      clientId: ${yamlString(musicSources.spotify.clientId)}
      clientSecret: ${yamlString(musicSources.spotify.clientSecret)}
      countryCode: ${yamlString(musicSources.spotify.countryCode)}
      playlistLoadLimit: ${musicSources.spotify.playlistLoadLimit}
      albumLoadLimit: ${musicSources.spotify.albumLoadLimit}
      resolveArtistsInSearch: ${musicSources.spotify.resolveArtistsInSearch}
`
    : ""
}${
  appleReady
    ? `    applemusic:
      countryCode: ${yamlString(musicSources.appleMusic.countryCode)}
      mediaAPIToken: ${yamlString(musicSources.appleMusic.mediaApiToken)}
      playlistLoadLimit: ${musicSources.appleMusic.playlistLoadLimit}
      albumLoadLimit: ${musicSources.appleMusic.albumLoadLimit}
`
    : ""
}${
  deezerReady
    ? `    deezer:
      arl: ${yamlString(musicSources.deezer.arl)}
      masterDecryptionKey: ${yamlString(musicSources.deezer.masterDecryptionKey)}
      formats: [ "MP3_320", "MP3_256", "MP3_128" ]
`
    : ""
  }`
    : "";

  return `${MARKER}
# File ini ditulis ulang setiap kali bot start. Jangan edit manual.
# Ubah nilainya lewat .env (LAVALINK_* / YOUTUBE_*).

server:
  port: ${port}
  address: 0.0.0.0

lavalink:
  plugins:
    - dependency: "dev.lavalink.youtube:youtube-plugin:${youtubePlugin}"
      snapshot: false${lavasrcPlugin}
  server:
    password: ${yamlString(password)}
    sources:
      youtube: false
      bandcamp: true
      soundcloud: true
      twitch: false
      vimeo: false
      nico: false
      http: true
      local: false
    filters:
      volume: true
      equalizer: true
      karaoke: true
      timescale: true
      tremolo: true
      vibrato: true
      distortion: true
      rotation: true
      channelMix: true
      lowPass: true
    bufferDurationMs: 400
    frameBufferDurationMs: 5000
    opusEncodingQuality: 10
    resamplingQuality: HIGH
    trackStuckThresholdMs: 10000
    useSeekGhosting: true
    youtubePlaylistLoadLimit: 6
    playerUpdateInterval: 5
    youtubeSearchEnabled: true
    soundcloudSearchEnabled: true
    gc-warnings: true

plugins:
  youtube:
    enabled: true
    allowSearch: true
    allowDirectVideoIds: true
    allowDirectPlaylistIds: true
${oauth}
${pot}
${remoteCipher}
    clients:
${clients}
${lavasrcBlock}
metrics:
  prometheus:
    enabled: false
    endpoint: /metrics

sentry:
  dsn: ""
  environment: ""

logging:
  file:
    path: ./logs/
  level:
    root: ${String(config.logLevel || "info").toUpperCase()}
    lavalink: INFO
    dev.lavalink.youtube: INFO
  logback:
    rollingpolicy:
      max-file-size: 25MB
      max-history: 7
`;
}

/**
 * Writes application.yml when needed. Returns true when the file changed.
 */
export function writeLavalinkConfig({ force = false } = {}) {
  const target = config.paths.configFile;
  const content = renderLavalinkConfig();

  try {
    fs.mkdirSync(path.dirname(target), { recursive: true });

    if (!force && fs.existsSync(target)) {
      const existing = fs.readFileSync(target, "utf8");
      if (existing === content) return false;

      // Only overwrite files we own, or files that are clearly the old template.
      if (!existing.includes(MARKER) && !existing.includes("AUTO-GENERATED")) {
        const backup = `${target}.backup-${Date.now()}`;
        fs.copyFileSync(target, backup);
        log.warn({ backup }, "application.yml lama di-backup sebelum ditimpa konfigurasi baru");
      }
    }

    fs.writeFileSync(target, content, "utf8");
    fs.mkdirSync(path.join(config.paths.lavalinkDir, "plugins"), { recursive: true });
    log.debug({ file: target }, "application.yml Lavalink diperbarui");
    return true;
  } catch (error) {
    log.error({ error: error.message }, "Gagal menulis application.yml Lavalink");
    return false;
  }
}

export { MARKER };
